from base import *
P = lambda **k: F(age_years=29, **k)
# BP / pregnancy / postpartum
c(P(pregnant=True, gestation_weeks=34, bp_systolic=150, bp_diastolic=100, hypertensive_organ_damage=True), est=False, label="L-B5 34w 150/100 + seizures/visual loss (organ damage)")
c(P(pregnant=True, gestation_weeks=34, bp_systolic=150, bp_diastolic=100, hypertensive_organ_damage=True, urine_protein_strip="neg"), est=False, label="L-B7 same, urine protein neg")
c(P(pregnant=True, gestation_weeks=34, bp_systolic=150, bp_diastolic=100, mental_status="drowsy"), est=False, label="L-B6 34w 150/100 drowsy")
c(P(pregnant=True, gestation_weeks=34, bp_systolic=150, bp_diastolic=100, hypertensive_symptoms=True, urine_protein_strip="neg"), est=False, label="L-B2 34w 150/100 headache, protein neg")
c(P(pregnant=True, gestation_weeks=34, bp_systolic=150, bp_diastolic=100, urine_protein_strip="neg", **T1), label="L-B2b T1 pregnant 34w 150/100 protein neg")
c(P(pregnant=False, postpartum_weeks=3, bp_systolic=200, bp_diastolic=120, hypertensive_organ_damage=True), est=False, label="L-B4 3w postpartum 200/120 organ damage")
c(P(pregnant=False, postpartum_weeks=3, bp_systolic=145, bp_diastolic=95, urine_protein_strip="neg"), est=False, label="L-B10 3w postpartum 145/95 protein neg")
c(P(bp_systolic=170, bp_diastolic=115), est=False, label="L-B8 woman 29, pregnancy unanswered, 170/115")
c(P(bp_systolic=170, bp_diastolic=115, **T2), label="L-B8b same, known T2")
c(P(pregnant=True, gestation_weeks=12, bp_systolic=142, bp_diastolic=92, urine_protein_strip="1plus"), est=False, label="L-B9 12w 142/92 protein 1+")
c(M(age_years=60, **T2, bp_systolic=190, bp_diastolic=115, hypertensive_symptoms=True), label="L-B1 T2 190/115 'symptoms' box (confusion ticked there)")
c(P(pregnant=True, gestation_weeks=30, bp_systolic=165, bp_diastolic=105, hypertensive_organ_damage=True), est=False, label="L-B11 30w 165/105 organ damage")
c(F(age_years=15, pregnant=True, gestation_weeks=30, bp_systolic=150, bp_diastolic=100), band="adolescent", est=False, label="L-B12 15y pregnant 30w 150/100")
c(F(age_years=11, bp_systolic=150, bp_diastolic=100, pregnant=True, gestation_weeks=30), band="child", est=False, label="L-B13 11y child band pregnant true 150/100")
# hypoglycaemia
c(M(age_years=60, dm_status="known", capillary_glucose=3.5, mental_status="drowsy"), label="L-H1 known, list+type blank, drowsy 3.5")
c(M(age_years=60, dm_status="known", dm_type_recorded="unclassified", glucose_lowering_therapy=["metformin"], capillary_glucose=3.5), label="L-H3 metformin, unclassified 3.5")
c(M(age_years=60, dm_status="known", glucose_lowering_therapy=["metformin"], capillary_glucose=3.6), label="L-H12 metformin, type blank 3.6")
c(M(age_years=60, dm_type_recorded="type_2", capillary_glucose=3.5), label="L-H13 type_2 recorded, status+list blank 3.5")
c(M(age_years=60, dm_type_recorded="type_2", capillary_glucose=3.5, mental_status="drowsy"), label="L-H13b same drowsy")
c(M(age_years=60, dm_status="known", dm_type_recorded="type_2", glucose_lowering_therapy=["none"], capillary_glucose=3.5, mental_status="stupor"), label="L-H14 list 'none' stupor 3.5")
c(M(age_years=60, dm_status="known", dm_type_recorded="type_2", glucose_lowering_therapy=["metformin"], capillary_glucose=3.5, vomiting=True, sglt2=None) if False else M(age_years=60, dm_status="known", dm_type_recorded="type_2", glucose_lowering_therapy=["metformin"], capillary_glucose=3.5, vomiting=True), label="L-H15 metformin vomiting 3.5")
c(M(age_years=60, dm_status="known", dm_type_recorded="type_2", glucose_lowering_therapy=["metformin"], fasting_pg=3.5), label="L-H16 metformin lab fasting 3.5")
# child
c(M(age_years=8, glucose_lowering_therapy=["insulin"], deep_rapid_breathing=True, capillary_glucose=7.0), band="child", label="L-C1 child insulin status blank Kussmaul glu 7")
c(M(age_years=8, dm_type_recorded="type_1", mental_status="drowsy", capillary_glucose=7.0), band="child", label="L-C2 child T1 recorded status blank drowsy glu 7")
c(M(age_years=8, **T1, mental_status="drowsy", capillary_glucose=3.5), band="child", label="L-C3 child T1 drowsy 3.5")
c(M(age_years=8, **T1, vomiting=True, capillary_glucose=7.0, urine_ketones="neg"), band="child", label="L-C4 child T1 vomiting glu7 urine neg")
c(M(age_years=8, **T1, vomiting=True, capillary_glucose=7.0), band="child", label="L-C4b child T1 vomiting glu7 nothing else")
c(M(age_years=14, dm_status="known", dm_type_recorded="type_2", glucose_lowering_therapy=["metformin"], capillary_glucose=3.5), band="adolescent", label="L-C5 14y T2 metformin 3.5")
c(M(age_years=8, **T1, mental_status="drowsy"), band="child", label="L-C9 child T1 drowsy no glucose")
c(M(age_years=8, **T1, vomiting=True, urine_ketones="3plus"), band="child", label="L-C10 child T1 vomiting urine 3+ no glucose")
c(M(age_years=14, **T1, vomiting=True, glucose_meter_extreme="hi"), band="adolescent", label="L-C11 14y T1 vomiting meter HI")
# SGLT2 / adults
c(M(age_years=55, **T2, glucose_lowering_therapy=["metformin","sglt2_inhibitor"], mental_status="drowsy", capillary_glucose=8.0), label="L-S1 SGLT2 drowsy glu 8")
c(M(age_years=55, **T2, glucose_lowering_therapy=["metformin","sglt2_inhibitor"], deep_rapid_breathing=True, capillary_glucose=8.0), label="L-S2 SGLT2 Kussmaul glu 8")
c(M(age_years=40, dm_status="not_known", vomiting=True, capillary_glucose=28.0, urine_ketones="1plus"), est=False, site="district", label="L-A1 new adult district glu28 vomiting urine 1+")
c(M(age_years=40, **T2, glucose_lowering_therapy=["metformin"], vomiting=True, capillary_glucose=28.0, urine_ketones="neg"), label="L-A2 T2 vomiting glu 28 urine neg")
c(M(age_years=30, **T1, deep_rapid_breathing=True, capillary_glucose=3.5), label="L-A3 T1 Kussmaul glu 3.5")
